    params: () => this.clientId(),
    stream: ({ params }) => this.service.summary(params),
  });

  /** Which split form is open, if any: a payment received, or the client's held deposits. */
  protected readonly recordingPayment = signal<PaymentSource | null>(null);
  protected readonly paymentSaved = signal(false);
  protected readonly depositApplied = signal(false);
  private readonly paymentForm = viewChild(ClientPaymentForm);
  private readonly depositsPanel = viewChild(ClientDeposits);
  private readonly remittancesPanel = viewChild(ClientRemittances);
  private readonly creditPanel = viewChild(ClientCredit);
  private readonly agingPanel = viewChild(ClientAging);
  private readonly mergePanel = viewChild(ClientMerge);
  /** Set once the page is being left, so a merge finishing meanwhile does not pull the user back. */
  private leaving = false;

  /** Resolves to true once any payment being recorded, or merge under way, has finished, so the page can be left safely. */
  async canLeave(): Promise<boolean> {
    this.leaving = true;
    await Promise.all([this.paymentForm()?.settled(), this.mergePanel()?.settled()]);
    this.leaving = false;
    return true;
  }

  protected toggle(source: PaymentSource): void {
    this.recordingPayment.update((open) => (open === source ? null : source));
  }

  protected paymentRecorded(source: PaymentSource): void {
    this.recordingPayment.set(null);
    this.paymentSaved.set(source === 'payment');
    this.depositApplied.set(source === 'deposit');
    // A payment may use up the client's credit or leave some over as credit, so both panels can change.
    this.depositsPanel()?.reload();
    this.creditPanel()?.reload();
    this.agingPanel()?.reload();
    this.remittancesPanel()?.reload();
    this.client.reload();
  }

  protected creditRefunded(): void {
    this.depositsPanel()?.reload();
  }

  protected contactAdded(): void {
    this.summary.reload();
    // The first contact added becomes the main contact.
    if (!this.client.value()?.primaryContact) {
      this.client.reload();
    }
  }

  protected contactArchived(contact: Contact): void {
    this.summary.reload();
    // An archived contact is no longer the main contact.
    if (this.client.value()?.primaryContact?.id === contact.id) {
      this.client.update((c) => c && { ...c, primaryContact: null });
    }
  }

  protected currencyChanged(client: Client): void {
    this.client.set(client);
  }

  protected creditLimitChanged(client: Client): void {
    this.client.set(client);
  }

  protected paymentTermsChanged(client: Client): void {
    this.client.set(client);
  }

  protected clientMerged(kept: Client): void {
    // This client no longer exists; carry on at the one it was merged into, unless the user is already leaving.
    if (this.leaving) {
      return;
    }
    void this.router.navigate(['/clients', kept.id]);
  }

  protected primaryChanged(contact: Contact): void {
    this.client.update((c) => c && { ...c, primaryContact: { id: contact.id, name: contact.name } });
  }
}
package net.officefloor.hq.app.client;

import jakarta.validation.Valid;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/clients")
public class ClientController {

    private final ClientService service;

    public ClientController(ClientService service) {
        this.service = service;
    }

    @GetMapping
    public List<ClientResponse> list(@RequestParam(defaultValue = "false") boolean includeArchived) {
        return service.list(includeArchived);
    }

    /** How many clients are in each segment. */
    @GetMapping("/segments")
    public List<ClientSegmentResponse> segments() {
        return service.segments();
    }

    /** Downloads the client list as a CSV file; the X-Export-Count header says how many clients it holds. */
    @GetMapping(value = "/export", produces = "text/csv")
    public ResponseEntity<String> exportList(@RequestParam(defaultValue = "false") boolean includeArchived) {
        ClientListExport export = service.exportList(includeArchived);
        return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, ContentDisposition.attachment().filename("clients.csv").build().toString())
                .header("X-Export-Count", String.valueOf(export.count()))
                .contentType(new MediaType("text", "csv", StandardCharsets.UTF_8))
                .body(export.csv());
    }

    @GetMapping("/{id}")
    public ClientResponse get(@PathVariable Long id) {
        return service.get(id);
    }

    @GetMapping("/{id}/summary")
    public ClientSummaryResponse summary(@PathVariable Long id) {
        return service.summary(id);
    }

    /** Downloads the client's contact details as a CSV file. */
    @GetMapping(value = "/{id}/export", produces = "text/csv")
    public ResponseEntity<String> export(@PathVariable Long id) {
        return ResponseEntity.ok()
                .header(HttpHeaders.CONTENT_DISPOSITION, ContentDisposition.attachment().filename("client-" + id + ".csv").build().toString())
                .contentType(new MediaType("text", "csv", StandardCharsets.UTF_8))
                .body(service.exportContactDetails(id));
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ClientResponse create(@Valid @RequestBody ClientRequest request) {
        return service.create(request);
    }

    @PutMapping("/{id}")
    public ClientResponse update(@PathVariable Long id, @Valid @RequestBody ClientRequest request) {
        return service.update(id, request);
    }

    @PutMapping("/{id}/currency")
    public ClientResponse changeCurrency(@PathVariable Long id, @Valid @RequestBody ClientCurrencyRequest request) {
        return service.changeCurrency(id, request.currency());
    }

    @PutMapping("/{id}/credit-limit")
    public ClientResponse changeCreditLimit(@PathVariable Long id, @Valid @RequestBody ClientCreditLimitRequest request) {
        return service.changeCreditLimit(id, request.creditLimit());
    }

    @PutMapping("/{id}/payment-terms")
    public ClientResponse changePaymentTerms(@PathVariable Long id, @Valid @RequestBody ClientPaymentTermsRequest request) {
        return service.changePaymentTerms(id, request.paymentTermsDays());
    }

    @PutMapping("/{id}/early-payment-window")
    public ClientResponse changeEarlyPaymentWindow(@PathVariable Long id, @Valid @RequestBody ClientEarlyPaymentWindowRequest request) {
        return service.changeEarlyPaymentWindow(id, request.earlyPaymentWindowDays());
    }

    @PostMapping("/{id}/archive")
    public ClientResponse archive(@PathVariable Long id) {
        return service.archive(id);
    }

    @PostMapping("/{id}/restore")
    public ClientResponse restore(@PathVariable Long id) {
        return service.restore(id);
    }

    @PostMapping("/{id}/pin")
    public ClientResponse pin(@PathVariable Long id) {
        return service.pin(id);
    }

    @PostMapping("/{id}/unpin")
    public ClientResponse unpin(@PathVariable Long id) {
        return service.unpin(id);
    }

    @PostMapping("/{id}/merge")
    public ClientResponse merge(@PathVariable Long id, @Valid @RequestBody ClientMergeRequest request) {
        return service.merge(id, request.targetId());
    }
