package net.officefloor.hq.app.payment;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** An amount a client has paid against an invoice on a given day. */
@Entity
@Table(name = "payment")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "invoice_id", nullable = false)
    private Long invoiceId;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "paid_date", nullable = false)
    private LocalDate date;

    /** The lump payment this was split from; null when paid against the invoice on its own. */
    @Column(name = "client_payment_id")
    private Long clientPaymentId;

    /** The deposit application this was put toward the invoice from; null when it was not paid from deposits. */
    @Column(name = "deposit_application_id")
    private Long depositApplicationId;

    /** The share of the lump this was split from, in the lump's currency; null when not split from a lump. */
    @Column(name = "share_amount", precision = 12, scale = 2)
    private BigDecimal shareAmount;

    /** The currency the payment was received in, when not the invoice's; null when paid in the invoice's currency. */
    @Column(name = "paid_currency", length = 3)
    private String paidCurrency;

    /** What was received, in {@link #paidCurrency}; null when paid in the invoice's currency. */
    @Column(name = "paid_amount", precision = 12, scale = 2)
    private BigDecimal paidAmount;

    protected Payment() {
    }

    public Payment(Long invoiceId, BigDecimal amount, LocalDate date) {
        this.invoiceId = invoiceId;
        this.amount = amount.setScale(2);
        this.date = date;
    }

    public Payment(Long invoiceId, BigDecimal amount, LocalDate date, Long clientPaymentId) {
        this(invoiceId, amount, date);
        this.clientPaymentId = clientPaymentId;
    }

    /**
     * A share of a lump payment: {@code shareAmount} is taken out of the lump (in its currency) and {@code amount}
     * is what it settles on the invoice, converted into the invoice's currency.
     */
    public Payment(Long invoiceId, BigDecimal amount, LocalDate date, Long clientPaymentId, BigDecimal shareAmount) {
        this(invoiceId, amount, date, clientPaymentId);
        this.shareAmount = shareAmount.setScale(2);
    }

    /**
     * A payment received in another currency: {@code paidAmount} in {@code paidCurrency} was received and
     * {@code amount} is what it settles on the invoice, converted into the invoice's currency.
     */
    public static Payment inForeignCurrency(Long invoiceId, BigDecimal amount, LocalDate date, String paidCurrency,
            BigDecimal paidAmount) {
        Payment payment = new Payment(invoiceId, amount, date);
        payment.paidCurrency = paidCurrency;
        payment.paidAmount = paidAmount.setScale(2);
        return payment;
    }

    /** A share of a client's held deposits put toward an invoice. */
    public static Payment fromDeposits(Long invoiceId, BigDecimal amount, LocalDate date, Long depositApplicationId) {
        Payment payment = new Payment(invoiceId, amount, date);
        payment.depositApplicationId = depositApplicationId;
        return payment;
    }

    public Long getId() {
        return id;
    }

    public Long getInvoiceId() {
        return invoiceId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public Long getClientPaymentId() {
        return clientPaymentId;
    }

    public BigDecimal getShareAmount() {
        return shareAmount;
    }

    public String getPaidCurrency() {
        return paidCurrency;
    }

    public BigDecimal getPaidAmount() {
        return paidAmount;
    }

    public Long getDepositApplicationId() {
        return depositApplicationId;
    }
}
package net.officefloor.hq.app.payment;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A lump sum a client paid on a given day, split across several of their invoices. It may also use up the client's
 * credit first (held deposits, then unused credit notes); whatever of the money received is not needed is kept as
 * credit for the client.
 */
@Entity
@Table(name = "client_payment")
public class ClientPayment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id", nullable = false)
    private Long clientId;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "paid_date", nullable = false)
    private LocalDate date;

    /** Held deposits used up toward the invoices along with the money received. */
    @Column(name = "from_deposits", nullable = false, precision = 12, scale = 2)
    private BigDecimal fromDeposits = BigDecimal.ZERO.setScale(2);

    /** Unused credit notes used up toward the invoices along with the money received. */
    @Column(name = "from_credit_notes", nullable = false, precision = 12, scale = 2)
    private BigDecimal fromCreditNotes = BigDecimal.ZERO.setScale(2);

    /** Money received beyond what the invoices needed, kept as credit for the client. */
    @Column(name = "to_credit", nullable = false, precision = 12, scale = 2)
    private BigDecimal toCredit = BigDecimal.ZERO.setScale(2);

    protected ClientPayment() {
    }

    public ClientPayment(Long clientId, BigDecimal amount, LocalDate date) {
        this.clientId = clientId;
        this.amount = amount.setScale(2);
        this.date = date;
    }

    public ClientPayment(Long clientId, BigDecimal amount, LocalDate date, BigDecimal fromDeposits,
            BigDecimal fromCreditNotes, BigDecimal toCredit) {
        this(clientId, amount, date);
        this.fromDeposits = fromDeposits.setScale(2);
        this.fromCreditNotes = fromCreditNotes.setScale(2);
        this.toCredit = toCredit.setScale(2);
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public BigDecimal getFromDeposits() {
        return fromDeposits;
    }

    public BigDecimal getFromCreditNotes() {
        return fromCreditNotes;
    }

    public BigDecimal getToCredit() {
        return toCredit;
    }
}
package net.officefloor.hq.app.refund;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Unused credit paid back to a client on a given day, split between what came out of their held
 * deposits and what came out of their unused credit notes.
 */
@Entity
@Table(name = "refund")
public class Refund {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "client_id", nullable = false)
    private Long clientId;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "from_deposits", nullable = false, precision = 12, scale = 2)
    private BigDecimal fromDeposits;

    @Column(name = "from_credit_notes", nullable = false, precision = 12, scale = 2)
    private BigDecimal fromCreditNotes;

    @Column(name = "refunded_on", nullable = false)
    private LocalDate date;

    @Column(length = 500)
    private String note;

    protected Refund() {
    }

    public Refund(Long clientId, BigDecimal fromDeposits, BigDecimal fromCreditNotes, LocalDate date, String note) {
        this.clientId = clientId;
        this.fromDeposits = fromDeposits.setScale(2);
        this.fromCreditNotes = fromCreditNotes.setScale(2);
        this.amount = this.fromDeposits.add(this.fromCreditNotes);
        this.date = date;
        this.note = note;
    }

    public Long getId() {
        return id;
    }

    public Long getClientId() {
        return clientId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public BigDecimal getFromDeposits() {
        return fromDeposits;
    }

    public BigDecimal getFromCreditNotes() {
        return fromCreditNotes;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getNote() {
        return note;
    }
}
package net.officefloor.hq.app.payment;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /** An invoice's payments, oldest first. */
    List<Payment> findByInvoiceIdOrderByDateAscIdAsc(Long invoiceId);

    /** The payments split from a lump payment, in the order they were recorded. */
    List<Payment> findByClientPaymentIdOrderByIdAsc(Long clientPaymentId);

    /** Every payment against any of the given invoices. */
    List<Payment> findByInvoiceIdIn(Collection<Long> invoiceIds);

    /** Every payment made on or between the given dates. */
    List<Payment> findByDateBetween(LocalDate from, LocalDate to);

    /** Total paid against an invoice (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p WHERE p.invoiceId = :invoiceId")
    BigDecimal sumAmountByInvoiceId(Long invoiceId);

    /** Total paid against an invoice on days before the given date (zero when nothing was). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p WHERE p.invoiceId = :invoiceId AND p.date < :date")
    BigDecimal sumAmountByInvoiceIdPaidBefore(Long invoiceId, LocalDate date);

    /** Total paid against every invoice with any of the given statuses (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p, Invoice i"
            + " WHERE p.invoiceId = i.id AND i.status IN :statuses")
    BigDecimal sumAmountByInvoiceStatusIn(Collection<InvoiceStatus> statuses);

    /** Total paid against invoices with any of the given statuses, per client; clients with none are left out. */
    @Query("SELECT pr.client.id AS clientId, SUM(p.amount) AS total FROM Payment p, Invoice i JOIN i.project pr"
            + " WHERE p.invoiceId = i.id AND i.status IN :statuses GROUP BY pr.client.id")
    List<InvoiceRepository.ClientTotal> sumAmountByInvoiceStatusInPerClient(Collection<InvoiceStatus> statuses);

    /** Total paid against each of the given invoices; invoices with no payments are left out. */
    @Query("SELECT p.invoiceId AS invoiceId, SUM(p.amount) AS paid FROM Payment p"
            + " WHERE p.invoiceId IN :invoiceIds GROUP BY p.invoiceId")
    List<InvoicePaidTotal> sumAmountByInvoiceIds(Collection<Long> invoiceIds);

    /** How much has been paid against one invoice. */
    interface InvoicePaidTotal {
        Long getInvoiceId();

        BigDecimal getPaid();
    }
}
